CREATE TABLE IF NOT EXISTS inventory_reservations(order_id BIGINT UNSIGNED PRIMARY KEY,fingerprint CHAR(64) NOT NULL,status VARCHAR(16) NOT NULL,delivered BOOLEAN NOT NULL DEFAULT FALSE,reconcile_at DATETIME(3) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),INDEX ix_inventory_reconcile(status,reconcile_at));
CREATE TABLE IF NOT EXISTS inventory_reservation_lines(order_id BIGINT UNSIGNED NOT NULL,sku_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,base_price DECIMAL(15,0) NOT NULL,PRIMARY KEY(order_id,sku_id));
CREATE TABLE IF NOT EXISTS inventory_movements(movement_key VARCHAR(120) PRIMARY KEY,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS domain_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT,action VARCHAR(64) NOT NULL,entity_id BIGINT,reason VARCHAR(1500),created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
